from collections import deque

def is_connected_after_removal(removed):
    remaining = set(range(n)) - set(removed)
    if len(remaining) == 0:
        return False
    start = min(remaining)
    visited = set([start])
    queue = deque([start])
    while queue:
        u = queue.popleft()
        for v in adj[u]:
            if v in remaining and v not in visited:
                visited.add(v)
                queue.append(v)
    return visited == remaining

