# Let's double-check vertex connectivity using Menger's theorem via max flow on all pairs
# Build auxiliary directed graph for vertex splitting
# Each vertex u -> u_in, u_out with capacity 1, edges u_out -> v_in for original edges

def vertex_connectivity():
    # For each pair s,t, compute max number of internally vertex-disjoint s-t paths
    # which equals min vertex cut separating s,t (excluding s,t)
    # Use Edmonds-Karp on auxiliary network
    def max_flow(s, t):
        # Node splitting: original node i -> i*2 (in) and i*2+1 (out)
        # Source is s*2+1 (out), sink is t*2 (in)
        # But s and t themselves are not in the cut, so we don't split them with capacity 1
        # Actually standard approach: for all v except s,t, edge v_in -> v_out capacity 1
        # For s and t, edge v_in -> v_out capacity INF (or n)
        N = 2*n
        S = s*2+1
        T = t*2
        cap = [[0]*N for _ in range(N)]
        INF = n
        for v in range(n):
            if v == s or v == t:
                cap[2*v][2*v+1] = INF
            else:
                cap[2*v][2*v+1] = 1
        for u in range(n):
            for v in adj[u]:
                cap[2*u+1][2*v] = INF

        flow = 0
        while True:
            parent = [-1]*N
            parent[S] = S
            queue = deque([S])
            while queue and parent[T] == -1:
                u = queue.popleft()
                for v in range(N):
                    if parent[v] == -1 and cap[u][v] > 0:
                        parent[v] = u
                        queue.append(v)
            if parent[T] == -1:
                break
            f = INF
            v = T
            while v != S:
                u = parent[v]
                f = min(f, cap[u][v])
                v = u
            v = T
            while v != S:
                u = parent[v]
                cap[u][v] -= f
                cap[v][u] += f
                v = u
            flow += f
        return flow

    min_conn = n
    for s in range(n):
        for t in range(s+1, n):
            conn = max_flow(s, t)
            if conn < min_conn:
                min_conn = conn
                print(f"Pair ({s},{t}) has connectivity {conn}")
                if min_conn < 5:
                    return min_conn
    return min_conn

